FMeshContactGeneratorSettings::FMeshContactGeneratorSettings()
{
	HashSize = FMath::RoundUpToPowerOfTwo(Chaos_Collision_MeshManifoldHashSize);
	FaceNormalDotThreshold = Chaos_Collision_MeshContactNormalThreshold;
	EdgeNormalDotRejectTolerance = Chaos_Collision_MeshContactNormalRejectionThreshold;
	BackFaceCullTolerance = FReal(1.e-6);
	BarycentricTolerance = FReal(1.e-3);
	MaxContactsBufferSize = 1000;
	bCullBackFaces = true;
	bFixNormals = true;
	bSortByPhi = false;
	bSortForSolverConvergence = false;
	bUseTwoPassLoop = true;
}

// Loop over (the required subset of) all triangles and call the TriangleContactGenerator to create a manifold for each.
// TriangleContactGeneratorType: void(const FTriangle& Triangle, FContactPointManifold& OutContactPoints)
template<typename TriangleContactGeneratorType>
void GenerateMeshContacts(const TriangleContactGeneratorType& TriangleContactGenerator)
{
	if (!!Settings.bUseTwoPassLoop)
	{
		GenerateMeshContactsTwoPass<TriangleContactGeneratorType>(TriangleContactGenerator);
	}
	else
	{
		GenerateMeshContactsOnePass<TriangleContactGeneratorType>(TriangleContactGenerator);
	}
}

template<typename TriangleContactGeneratorType>
void GenerateMeshContactsTwoPass(const TriangleContactGeneratorType& TriangleContactGenerator)
{
	// First loop: Visit triangles that do not have any collisions on any of their vertices or edges.
	// This will skip all triangles whose neighbours have already been processed and generated a contact
	// on a shared edge/vertex.
	for (int32 LocalTriangleIndex = 0; LocalTriangleIndex < GetNumTriangles(); ++LocalTriangleIndex)
	{
		if (GetNumTriangleFaceCollisions(LocalTriangleIndex) == 0)
		{
			TriangleContactGenerator(*this, LocalTriangleIndex);

			SetTriangleVisited(LocalTriangleIndex, 0);
		}
	}

	// Second loop: Visit remaining triangles that have less than 3 contacts on them. This will skip all triangles
	// that have a full manifold as a result of collisions on shared edges/vertices from adjacent triangles.
	for (int32 LocalTriangleIndex = 0; LocalTriangleIndex < GetNumTriangles(); ++LocalTriangleIndex)
	{
		if (!IsTriangleVisited(LocalTriangleIndex) && (GetNumTriangleFaceCollisions(LocalTriangleIndex) < 3))
		{
			TriangleContactGenerator(*this, LocalTriangleIndex);

			SetTriangleVisited(LocalTriangleIndex, 1);
		}
	}
}

bool HasFaceVertexCollision(const FContactVertexID VertexID) const
{
	if (const FVertexContactData* ContactData = VertexContactDataMap.Find(VertexID))
	{
		return ContactData->bIsFaceContact;
	}
	return false;
}

int32 GetNumTriangleFaceCollisions(const int32 LocalTriangleIndex) const
{
	const int32 MeshVertexIndex0 = Triangles[LocalTriangleIndex].GetVertexIndex(0);
	const int32 MeshVertexIndex1 = Triangles[LocalTriangleIndex].GetVertexIndex(1);
	const int32 MeshVertexIndex2 = Triangles[LocalTriangleIndex].GetVertexIndex(2);
	int32 NumCollisions = Triangles[LocalTriangleIndex].GetNumFaceEdgeCollisions();
	NumCollisions += HasFaceVertexCollision(MeshVertexIndex0) ? 1 : 0;
	NumCollisions += HasFaceVertexCollision(MeshVertexIndex1) ? 1 : 0;
	NumCollisions += HasFaceVertexCollision(MeshVertexIndex2) ? 1 : 0;
	return NumCollisions;
}

bool IsTriangleVisited(const int32 LocalTriangleIndex) const
{
	return Triangles[LocalTriangleIndex].GetVisitIndex() != INDEX_NONE;
}

void SetTriangleVisited(const int32 LocalTriangleIndex, const int8 VisitIndex)
{
	Triangles[LocalTriangleIndex].SetVisitIndex(VisitIndex);
}

// Generate the contact manifold between Convex and a Triangle
const auto& GenerateConvexTriangleContacts =
	[&Convex, &ConvexTransform, CullDistance](Private::FMeshContactGenerator& ContactGenerator, const int32 TriangleIndex)
{
	FContactPointManifold Contacts;
	GenerateConvexTriangleOneShotManifold(Convex, ConvexTransform, ContactGenerator, TriangleIndex, CullDistance, Contacts);

	ContactGenerator.AddTriangleContacts(TriangleIndex, MakeArrayView(Contacts));
};

// Collect all the triangles that overlap our convex. Triangles will be in Convex space
Mesh.CollectTriangles(MeshQueryBounds, MeshToConvexTransform, ConvexBounds, ContactGenerator);

// Generate a set of contact points for all triangles
ContactGenerator.GenerateMeshContacts(GenerateConvexTriangleContacts);

// Process the contacts to minimize manifold etc
ContactGenerator.ProcessGeneratedContacts(ConvexTransform, MeshToConvexTransform);

void ConstructQuadraticConvexTriMeshOneShotManifold(const FImplicitObject& Quadratic, const FRigidTransform3& QuadraticTransform, const FImplicitObject& InMesh, const FRigidTransform3& MeshTransform, const FReal Dt, FPBDCollisionConstraint& Constraint)
{
	// All convexes are pre-scaled, or wrapped in TImplicitObjectScaled
	ensure(QuadraticTransform.GetScale3D() == FVec3(1));
	ensure(MeshTransform.GetScale3D() == FVec3(1));

	// Unwrap the tri mesh (remove Scaled or Instanced) and get the scale
	FVec3 MeshScale;
	FReal MeshMargin;	// Not used - will be zero for meshes
	const FTriangleMeshImplicitObject* Mesh = UnwrapImplicit<FTriangleMeshImplicitObject>(InMesh, MeshScale, MeshMargin);
	check(Mesh != nullptr);

	const FReal CullDistance = Constraint.GetCullDistance();

	if (bChaos_Collision_EnableMeshManifoldOptimizedLoop)
	{
		// New version uses a two-pass loop over triangles to avoid visiting triangles whose vertices are all colliding as a result of checking adjacent triangles
		Private::FMeshContactGeneratorSettings ContactGeneratorSettings;
		ContactGeneratorSettings.FaceNormalDotThreshold = 0.9999;	// ~0.8deg Normals must be accurate or rolling will not work correctly
		ContactGeneratorSettings.bUseTwoPassLoop = false;			// two-pass loop is not helpful for capsules and spheres
		ContactGeneratorSettings.bSortByPhi = bChaos_Collision_ConvexTriMeshSortByPhi;
		ContactGeneratorSettings.bSortForSolverConvergence = bChaos_Collision_ConvexTriMeshSortByDistance && !bChaos_Collision_ConvexTriMeshSortByPhi;
		Private::FMeshContactGenerator ContactGenerator(ContactGeneratorSettings);

		const FVec3 RelativeMovement = FVec3(Constraint.GetRelativeMovement());

		if (const FImplicitSphere3* Sphere = Quadratic.template GetObject<FImplicitSphere3>())
		{
			ConstructConvexMeshOneShotManifoldMACD(*Sphere, QuadraticTransform, *Mesh, MeshTransform, MeshScale, RelativeMovement, CullDistance, ContactGenerator);
		}
		else if (const FImplicitCapsule3* Capsule = Quadratic.template GetObject<FImplicitCapsule3>())
		{
			ConstructConvexMeshOneShotManifold2(*Capsule, QuadraticTransform, *Mesh, MeshTransform, MeshScale, CullDistance, ContactGenerator);
		}
		else
		{
			check(false);
		}

		Constraint.SetOneShotManifoldContacts(ContactGenerator.GetContactPoints());
	}

if (bChaos_Collision_EnableMeshManifoldOptimizedLoop_TriMesh)
{
	const FVec3 RelativeMovement = FVec3(Constraint.GetRelativeMovement());
	Private::FMeshContactGeneratorSettings ContactGeneratorSettings;
	ContactGeneratorSettings.bSortByPhi = bChaos_Collision_ConvexTriMeshSortByPhi;
	ContactGeneratorSettings.bSortForSolverConvergence = bChaos_Collision_ConvexTriMeshSortByDistance && !bChaos_Collision_ConvexTriMeshSortByPhi;
	Private::FMeshContactGenerator ContactGenerator(ContactGeneratorSettings);

	if (const FImplicitBox3* RawBox = Convex.template GetObject<FImplicitBox3>())
	{
		ConstructConvexMeshOneShotManifoldMACD(*RawBox, ConvexTransform, *Mesh, MeshTransform, MeshScale, RelativeMovement, CullDistance, ContactGenerator);
	}
	else if (const TImplicitObjectScaled<FImplicitConvex3>* ScaledConvex = Convex.template GetObject<TImplicitObjectScaled<FImplicitConvex3>>())
	{
		ConstructConvexMeshOneShotManifoldMACD(*ScaledConvex, ConvexTransform, *Mesh, MeshTransform, MeshScale, RelativeMovement, CullDistance, ContactGenerator);
	}
	else if (const TImplicitObjectInstanced<FImplicitConvex3>* InstancedConvex = Convex.template GetObject<TImplicitObjectInstanced<FImplicitConvex3>>())
	{
		ConstructConvexMeshOneShotManifoldMACD(*InstancedConvex, ConvexTransform, *Mesh, MeshTransform, MeshScale, RelativeMovement, CullDistance, ContactGenerator);
	}
	else if (const FImplicitConvex3* RawConvex = Convex.template GetObject<FImplicitConvex3>())
	{
		ConstructConvexMeshOneShotManifoldMACD(*RawConvex, ConvexTransform, *Mesh, MeshTransform, MeshScale, RelativeMovement, CullDistance, ContactGenerator);
	}
	else
	{
		check(false);
	}

	Constraint.SetOneShotManifoldContacts(ContactGenerator.GetContactPoints());

FMeshContactGeneratorSettings();

// Contacts with a dot product against the face normal above this value will not be processed in FixContactNormal
FReal FaceNormalDotThreshold;

// Triangle edge/vertex contacts that are more than this far from a valid normal (dot product) will be rejected rather than corrected
FReal EdgeNormalDotRejectTolerance;

// When backface culling is enabled, the tolerance for the dot product of the contact normal against the face normal
FReal BackFaceCullTolerance;

// Used to determine whether a contact is on an edge or vertex
FReal BarycentricTolerance;

// We don't allow more (pre-filtered) contacts than this. Any extras will be lost.
int32 MaxContactsBufferSize;

// Size of the hash table used to store/lookup triangle data
int32 HashSize;

// Whether to ignore inside normals
// @todo(chaos): the non-culled option is not well tested and probably broken
uint32 bCullBackFaces : 1;

// Whether to auto-correct normals
uint32 bFixNormals : 1;

// Whether to sort the contacts by depth
uint32 bSortByPhi : 1;

// Whether to sort the contacts to improve solver convergence (distance from the center of mass)
uint32 bSortForSolverConvergence : 1;

// Whether to use the optimized two-pass loop over triangles in GenerateMeshContacts which skips triangles
// that have contacts on all vertices in the second pass. This is only useful when this case occurs a lot
// which is does for large convexes against many triangles, but rarely for capsules and spheres.
uint32 bUseTwoPassLoop : 1;

template <typename TriMeshType>
void UpdateCapsuleTriangleMeshConstraint(const FCapsule& Capsule0, const FRigidTransform3& WorldTransform0, const TriMeshType& TriangleMesh1, const FRigidTransform3& WorldTransform1, const FReal Dt, FPBDCollisionConstraint& Constraint)
{
	// @todo(chaos): restitution padding
	CONDITIONAL_SCOPE_CYCLE_COUNTER(STAT_Collisions_UpdateCapsuleTriangleMeshConstraint, ConstraintsDetailedStats);
	if (Constraint.GetUseManifold())
	{
		ConstructQuadraticConvexTriMeshOneShotManifold(Capsule0, WorldTransform0, TriangleMesh1, WorldTransform1, Dt, Constraint);
	}
	else
	{
		UpdateContactPoint(Constraint, CapsuleTriangleMeshContactPoint(Capsule0, WorldTransform0, TriangleMesh1, WorldTransform1, Constraint.GetCullDistance()), Dt);
	}
}
